"use client";
import { useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { upload, uploadPresigned } from "@vercel/blob/client";
import { FileText, Paperclip, Upload } from "lucide-react";
import { finalizeResume, removeResume } from "@/lib/resume-actions";
import { Button } from "@/components/ui/button";
import { Feedback } from "@/components/forms";
import type { ActionResult } from "@/lib/errors";
import { MAX_PDF_BYTES } from "@/lib/validation";
import { SettingsPanel } from "./SettingsPanel";
import { SavedStatus } from "./SavedStatus";
import styles from "./settings.module.css";
export function ResumeUpload({
  userId,
  fileName,
  useBlob,
  usePresignedBlob,
}: {
  userId: string;
  fileName: string | null;
  useBlob: boolean;
  usePresignedBlob: boolean;
}) {
  const [result, setResult] = useState<ActionResult>();
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [dragging, setDragging] = useState(false);
  const validFile =
    !!selectedFile &&
    selectedFile.type === "application/pdf" &&
    selectedFile.size <= MAX_PDF_BYTES;
  function choose(file: File | null) {
    setSelectedFile(file);
    setResult(
      file && (file.type !== "application/pdf" || file.size > MAX_PDF_BYTES)
        ? { ok: false, message: "Must be a PDF up to 5 MB" }
        : undefined,
    );
  }
  const [pending, start] = useTransition();
  const input = useRef<HTMLInputElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const router = useRouter();
  return (
    <SettingsPanel
      id="resume"
      title="PDF attachment"
      icon={FileText}
      description="Upload one PDF, such as a resume, portfolio, or brochure, up to 5 MB. Select “Attach PDF” in Compose to include it. Queued emails keep the PDF selected when sending."
    >
      {fileName && (
        <div className="flex flex-wrap items-center justify-between gap-3">
          <a
            href="/api/resume/download"
            className={`text-[var(--settings-purple)] font-semibold no-underline wrap-anywhere css-hover:underline inline-flex items-center min-h-11 flex min-w-0 items-center gap-2 break-all text-sm`}
          >
            <Paperclip className="size-4 shrink-0" aria-hidden="true" />
            {fileName}
          </a>
          <Button
            className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
            variant="ghost"
            disabled={pending}
            onClick={() => dialog.current?.showModal()}
          >
            Remove
          </Button>
        </div>
      )}
      <form
        className="mt-4 space-y-4"
        action={() =>
          start(async () => {
            const file = selectedFile;
            if (!file) {
              setResult({ ok: false, message: "Choose a PDF first." });
              input.current?.focus();
              return;
            }
            if (file.type !== "application/pdf" || file.size > MAX_PDF_BYTES) {
              setResult({ ok: false, message: "Must be a PDF up to 5 MB" });
              input.current?.focus();
              return;
            }
            try {
              if (useBlob) {
                const pathname = `resumes/${userId}/${crypto.randomUUID()}.pdf`;
                const uploadFile = usePresignedBlob ? uploadPresigned : upload;
                await uploadFile(pathname, file, {
                  access: "private",
                  handleUploadUrl: "/api/resume/blob",
                });
                setResult(await finalizeResume(pathname, file.name));
              } else {
                const form = new FormData();
                form.set("file", file);
                const response = await fetch("/api/resume/upload", {
                  method: "POST",
                  body: form,
                });
                const data = await response.json();
                setResult({
                  ok: response.ok,
                  message:
                    data.error ??
                    "PDF saved. Select “Attach PDF” in Compose to include it.",
                });
              }
              router.refresh();
            } catch {
              setResult({
                ok: false,
                message: "Upload failed. Check your connection and try again.",
              });
            }
          })
        }
      >
        <label
          htmlFor="resume-file"
          className={`flex items-center gap-3.5 p-4.5 rounded-[var(--appearance-radius,_16px)] [border:1.5px_dashed_var(--settings-strong)] cursor-pointer css-hover:[background:var(--appearance-wash,_var(--color-settings-background-33))] [&:focus-within]:[outline:2px_solid_var(--settings-pink)] [&:focus-within]:[outline-offset:3px] [@media(width_<_480px)]:p-3.5 [@media(width_<_480px)]:gap-2.5 ${dragging ? "[background:var(--appearance-wash,_var(--color-settings-background-33))]" : ""}`}
          onDragOver={(event) => {
            event.preventDefault();
            if (!pending) setDragging(true);
          }}
          onDragLeave={(event) => {
            if (
              !event.currentTarget.contains(event.relatedTarget as Node | null)
            )
              setDragging(false);
          }}
          onDrop={(event) => {
            event.preventDefault();
            setDragging(false);
            if (!pending) choose(event.dataTransfer.files[0] ?? null);
          }}
        >
          <span
            className={`w-10 h-10 inline-grid place-items-center flex-none rounded-[var(--appearance-radius,_12px)] [background:var(--appearance-wash,_var(--color-settings-background-27))] text-[var(--settings-purple)] workspace-icon-tile`}
          >
            <Upload size={20} aria-hidden="true" />
          </span>
          <span className="min-w-0">
            <span className="block break-all text-sm font-bold">
              {selectedFile?.name ?? fileName ?? "Upload PDF"}
            </span>
            <span
              className={`text-[var(--settings-muted)] text-[14px] leading-[1.65] block`}
              aria-live="polite"
            >
              {selectedFile
                ? validFile
                  ? `${(selectedFile.size / (1024 * 1024)).toFixed(2)} MB · Ready to save`
                  : "Must be a PDF up to 5 MB"
                : "Click to select a PDF · Up to 5 MB"}
            </span>
          </span>
          <input
            ref={input}
            className="sr-only"
            id="resume-file"
            name="file"
            type="file"
            accept="application/pdf"
            aria-label={fileName ? "Replace PDF" : "Upload PDF"}
            disabled={pending}
            onChange={(event) => choose(event.target.files?.[0] ?? null)}
          />
        </label>
        <div className="flex flex-wrap items-center gap-3.5 mt-6">
          <button
            className={`${styles.primary} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none [border:1px_solid_transparent] text-[var(--primary-action-ink)] [background:var(--primary-action-gradient)] shadow-none`}
            type="submit"
            disabled={pending || !validFile}
          >
            {pending ? "Uploading…" : "Save PDF"}
          </button>
          <SavedStatus result={result} />
        </div>
      </form>
      {result?.ok === false && <Feedback result={result} />}
      <dialog
        ref={dialog}
        className={`${styles.dialog} m-auto w-[calc(100%_-_2rem)] max-w-128 max-h-[calc(100dvh_-_2rem)] overflow-y-auto [border:1px_solid_var(--settings-strong)] rounded-[var(--appearance-radius,_24px)] p-7 [background:var(--settings-elevated)] text-[var(--settings-text)] shadow-[var(--appearance-shadow,_0_16px_64px_var(--color-settings-box-shadow-35))]`}
        aria-labelledby="remove-resume-title"
        onCancel={(event) => {
          if (pending) event.preventDefault();
        }}
      >
        <h2 id="remove-resume-title" className="text-xl font-semibold">
          Remove your PDF attachment?
        </h2>
        <p className="mt-3 text-sm text-body">
          Future campaigns will have no attachment. Queued emails keep their
          saved attachment.
        </p>
        <div className="mt-6 flex justify-end gap-2">
          <Button
            className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
            disabled={pending}
            variant="outline"
            onClick={() => dialog.current?.close()}
          >
            Cancel
          </Button>
          <Button
            className={`${styles.dangerButton} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer [border:1px_solid_var(--settings-danger-border)] text-[var(--settings-red)] [background:transparent] shadow-[var(--appearance-shadow,_none)] css-hover:[background:var(--settings-danger-background)]`}
            variant="destructive"
            disabled={pending}
            onClick={() =>
              start(async () => {
                setResult(await removeResume());
                dialog.current?.close();
                router.refresh();
              })
            }
          >
            Remove
          </Button>
        </div>
      </dialog>
    </SettingsPanel>
  );
}
